import math


def fit_nb(docs, labels):
    if not docs or len(docs) != len(labels):
        raise ValueError('need documents, one label each')
    vocab = {w for doc in docs for w in doc}
    model = {'vocab': vocab, 'classes': {}}
    for c in sorted(set(labels)):
        words = [w for doc, l in zip(docs, labels) if l == c for w in doc]
        model['classes'][c] = {'prior': labels.count(c) / len(labels), 'counts': {w: words.count(w) for w in vocab}, 'total': len(words)}
    return model


def nb_scores(model, doc):
    scores = {}
    V = len(model['vocab'])
    for c, info in model['classes'].items():
        s = math.log(info['prior'])
        for w in doc:
            if w in model['vocab']:
                s += math.log((info['counts'][w] + 1) / (info['total'] + V))
        scores[c] = s
    return scores


def predict_nb(model, doc):
    scores = nb_scores(model, doc)
    top = max(scores.values())
    return min(c for c in scores if scores[c] >= top - 1e-9)

